class MdxCodeBlockUnwrapper {
  private readonly tripleFencePattern = tripleMdxFencePattern;
  private readonly quadrupleFencePattern = quadrupleMdxFencePattern;

  unwrapMdxCodeBlocks(content: string): string {
    // We only support 3/4 backticks on purpose, should be good enough
    const regexp3 = new RegExp(
      `(?<begin>^|\\n)${this.tripleFencePattern.escapedFence}(?<spaces>${this.tripleFencePattern.spaceClass}*)${this.tripleFencePattern.infoLabel}\\n(?<children>.*?)\\n${this.tripleFencePattern.escapedFence}(?<end>\\n|$)`,
      this.tripleFencePattern.flags,
    );
    const regexp4 = new RegExp(
      `(?<begin>^|\\n)${this.quadrupleFencePattern.escapedFence}(?<spaces>${this.quadrupleFencePattern.spaceClass}*)${this.quadrupleFencePattern.infoLabel}\\n(?<children>.*?)\\n${this.quadrupleFencePattern.escapedFence}(?<end>\\n|$)`,
      this.quadrupleFencePattern.flags,
    );

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const replacer = (substring: string, ...args: any[]) => {
      const groups = args.at(-1);
      const capture = new MdxCodeBlockCapture(
        groups.begin,
        groups.children,
        groups.end,
      );
      return `${capture.begin}${capture.children}${capture.end}`;
    };

    return content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
  }
}

const mdxCodeBlockUnwrapper = new MdxCodeBlockUnwrapper();

/**
 * Hacky temporary escape hatch for Crowdin bad MDX support
 * See https://docusaurus.io/docs/i18n/crowdin#mdx
 *
